"""Content data: aws-clf (part 2 of 2) — analytics-overview, migration, well-architected + labs 5-8."""
from cbt_builder import L, S, LB, D
CN = 'AWS Cloud Practitioner'

def build_awsclf2():
    new_domains = []
    labs = []

    def std(did, name, desc, lesson_specs, scen_specs, icon=None):
        lessons = [L(did, *sp) for sp in lesson_specs]
        scenarios = [S(did, *sp) for sp in scen_specs]
        new_domains.append(D(did, name, desc, lessons, scenarios, icon=icon))
    did = 'analytics-overview'
    (std(did, 'Analytics Services Overview', 'Athena, EMR, Glue, Kinesis, and QuickSight: the analytics pipeline from raw data to dashboards for CLF-C02.', [('Athena: SQL on S3', ['Athena runs standard SQL directly against data in S3 — no servers, no loading: define the table schema, point at the bucket, and query', 'Serverless and pay-per-query: you pay for the data scanned ($5/TB), so partitioning and columnar formats (Parquet) slash the bill', 'Best for ad-hoc exploration: log analysis, one-off investigations, and occasional reporting — not for dashboards hit 1000x a day', 'Integrates with Glue Data Catalog for table definitions and QuickSight for visualization'], 'Cost math:\n  1 TB CSV scanned per query x 20 queries/day\n  = $100/day. Convert to Parquet + partition by date:\n  50 GB scanned per query -> $5/day.\n\nFormat is pricing.', "Athena's exam trap is the 'data scanned' pricing: every question about Athena cost optimization answers with partitioning, compression, and columnar formats. Unpartitioned CSV is the expensive wrong answer.", ['Querying raw CSV dumps repeatedly — maximum scan cost', 'Athena for high-QPS dashboards — use Redshift or cached aggregates', 'No partitioning on time-series data'], 'Your Athena bill tripled: name three changes that cut data scanned per query.'), ('EMR: Big Data Processing', ['EMR runs Hadoop, Spark, and Presto clusters: petabyte-scale batch processing, machine learning prep, and large ETL jobs', 'Managed but not serverless: you choose instance types and counts — EMR handles provisioning, patching, and framework setup', 'Transient clusters are the cost trick: spin up for the job, terminate after — you pay only for processing time, not idle clusters', 'Exam contrast: EMR = big batch frameworks you manage at cluster level; Glue = serverless ETL you do not manage'], 'EMR vs Glue:\n  Nightly 2 TB Spark job, custom libs -> EMR transient\n  Daily CSV -> Parquet ETL -> Glue (serverless)\n  Ad-hoc SQL on logs -> Athena\n  Streaming clickstream -> Kinesis + Firehose\n\nFramework + duration decide.', "Do not pick EMR for small data: the cluster overhead (spin-up time, minimum sizing) makes it the slow expensive choice under ~100 GB. The exam tests 'right-sized analytics' — match the engine to the data volume.", ['EMR for 10 GB datasets — cluster overhead dominates', '24/7 EMR cluster for a nightly 1-hour job — use transient', 'Confusing EMR (frameworks) with Redshift (warehouse SQL)'], '2 TB nightly Spark ETL, custom Python libs: EMR or Glue? What cluster pattern?'), ('Glue: Serverless ETL and Data Catalog', ['Glue is serverless ETL: visually or code-authored jobs that extract, transform, and load data — no clusters to manage', 'Glue Data Catalog is the metadata hub: table definitions shared by Athena, Redshift Spectrum, and EMR — define once, query everywhere', 'Crawlers auto-discover schema: point a crawler at S3 and it infers tables — the fastest path from raw dumps to queryable data', 'Pay per DPU-second: cost follows actual processing — ideal for scheduled or event-driven ETL that does not justify a standing cluster'], 'Glue pipeline:\n  S3 raw CSV -> Crawler (catalog) -> Glue job (clean + Parquet)\n  -> S3 curated -> Athena/QuickSight\n\nCatalog once, consume everywhere.', "Glue's exam identity is 'serverless + catalog': any question pairing ETL with 'no infrastructure to manage' or mentioning the Data Catalog points to Glue. Crawlers are the giveaway keyword for schema discovery.", ['Hand-writing DDL for 500 evolving CSV dumps — use a crawler', 'Glue for sub-second streaming — use Kinesis', 'Rebuilding table definitions per service — use the shared Catalog'], 'Raw CSVs land in S3 hourly; analysts need clean Parquet by morning: sketch the Glue flow.'), ('Kinesis: Real-Time Streaming', ['Kinesis Data Streams: real-time ingestion of clickstreams, IoT telemetry, and logs — producers write, consumers process in order per shard', 'Amazon Data Firehose: the zero-admin loader — streams land in S3, Redshift, or OpenSearch with batching, compression, and format conversion built in', 'Streams vs Firehose: Streams = you manage consumers and scaling (full control); Firehose = managed delivery to destinations (simplicity)', "Exam heuristic: 'real-time analytics with custom processing' → Data Streams; 'load streaming data into S3/Redshift easily' → Firehose"], 'Streaming choice:\n  Fraud detection, custom per-event logic -> Data Streams\n  Clickstream -> S3 data lake, no custom code -> Firehose\n  IoT -> OpenSearch dashboards -> Firehose\n  Ordered per-user event processing -> Data Streams (shard per user)\n\nCustom logic decides.', "Shards are the scaling unit of Data Streams: each shard gives ~1 MB/s in, 2 MB/s out — throughput planning is shard math. The exam rarely goes this deep, but 'res hard per shard' separates Streams from the fully-managed Firehose.", ['Firehose when custom per-record processing is required', 'Data Streams for simple S3 delivery — overkill', 'No shard planning on high-throughput Streams'], 'IoT sensors stream 5k events/sec to S3 for Athena queries: Streams or Firehose? Why?'), ('QuickSight and the Analytics Pipeline', ['QuickSight is serverless BI: dashboards and visualizations with pay-per-session pricing — no BI servers to run', 'SPICE (in-memory engine) accelerates dashboards: import data for fast queries; direct query for live data — speed vs freshness tradeoff', 'The full pipeline: ingest (Kinesis/Firehose, DMS) → store (S3 data lake, Redshift) → catalog (Glue) → analyze (Athena/EMR) → visualize (QuickSight)', "Exam view: QuickSight = 'dashboards without servers'; know its place at the END of the pipeline, consuming from S3, Athena, RDS, or Redshift"], 'Pipeline map:\n  Sources -> [Firehose/DMS] -> S3 lake\n  S3 lake -> [Glue catalog] -> Athena (ad-hoc)\n  S3 lake -> Redshift (heavy BI)\n  Athena/Redshift -> QuickSight dashboards\n\nEach stage has one job.', "Place every analytics service on the pipeline before memorizing features: ingestion, storage, catalog, processing, visualization. CLF-C02 questions describe a STAGE ('we need dashboards') — the service follows from the stage.", ['QuickSight querying raw CSV in S3 directly at scale — curate first', 'Building the pipeline backwards from the dashboard', 'One service doing every stage — pipeline thinking wins'], "Draw the 5-stage pipeline for 'clickstream to executive dashboard' naming the AWS service per stage.")], [('clf-an-athena', 'The Log Query Bill', 'Your team queries 2 TB of ALB logs in S3 with Athena daily. The bill is $300/month and growing. The logs are raw CSV, unpartitioned.', 'What cuts the Athena cost most?', ['Convert to Parquet, partition by date, and compress: columnar format + partition pruning slashes data scanned per query — the dominant cost lever since Athena bills per TB scanned.', 'Query less often.', 'Move to Redshift.', 'Delete old logs.'], 0, "The correct answer attacks the pricing model: Athena charges per TB scanned, so Parquet (columnar, compressed) plus date partitioning (prune irrelevant data) multiplies down every query's cost. Querying less treats the symptom.", 'How does Athena pricing make format and partitioning a cost decision?', ['Optimize Athena with Parquet and partitioning', 'Understand pay-per-TB-scanned', 'Apply columnar formats'], 10, [['Bill', '2 TB raw CSV scanned daily; $300/mo and growing']]), ('clf-an-emr', 'The Nightly Spark Job', "A data team runs a 90-minute Spark job nightly on 1.5 TB. They keep an EMR cluster running 24/7 'so it is ready.'", 'What is the cost fix?', ['Run the job weekly instead.', "Transient EMR clusters: spin up for the 90-minute job, terminate after — 22.5 idle hours a day of cluster cost vanishes; EMR's managed setup makes spin-up cheap.", 'Bigger instances for the 24/7 cluster.', 'Move to Lambda.'], 1, "The correct answer kills the idle time: a nightly 90-minute job needs ~2 hours of cluster, not 24. Transient clusters are EMR's core cost pattern; Lambda cannot run 90-minute Spark.", "What is EMR's cost-optimal pattern for scheduled batch?", ['Use transient EMR clusters', 'Eliminate idle cluster cost', 'Right-size batch infrastructure'], 10, [['Waste', '24/7 cluster, 90 min/night utilized; 94% idle']]), ('clf-an-glue', 'The Schema Drift', 'Marketing uploads CSVs with changing columns weekly. Analysts hand-edit table definitions each time before Athena queries work.', 'What automates this?', ['EMR cluster.', 'Manual DDL with version control.', 'A Glue crawler: it scans the S3 data, infers schema changes, and updates the Data Catalog — Athena queries keep working without hand-edited DDL.', 'A larger Athena workgroup.'], 2, "The correct answer is Glue's signature feature: crawlers auto-discover and evolve schema in the shared Catalog. Hand-maintaining DDL against weekly drift is toil the crawler eliminates.", 'Which Glue feature handles evolving schemas automatically?', ['Use Glue crawlers for schema discovery', 'Centralize metadata in the Catalog', 'Eliminate manual DDL toil'], 10, [['Toil', 'Weekly column changes; analysts hand-edit DDL; queries break regularly']]), ('clf-an-kinesis', 'The Clickstream Loader', 'Product wants clickstream events in the S3 data lake within minutes, queryable by Athena. No custom per-event logic needed; the team is small.', 'Which ingestion service fits?', ['Kinesis Data Streams with custom consumers.', 'EMR streaming.', 'DMS.', 'Amazon Data Firehose: managed streaming delivery to S3 with batching, compression, and Parquet conversion — no consumer code or shard management for the small team.'], 3, "The correct answer picks managed over flexible: with no custom processing and a small team, Firehose's zero-admin delivery beats Data Streams' consumer/shard management. EMR and DMS are wrong stages entirely.", 'When does Firehose beat Data Streams?', ['Choose Firehose for managed delivery', 'Match service to team capacity', 'Land streams in S3 for Athena'], 10, [['Needs', 'Clickstream -> S3 in minutes; no custom logic; 3-person team']]), ('clf-an-quicksight', 'The Dashboard Ask', 'Executives want daily sales dashboards. No BI infrastructure exists, usage is 20 viewers, and IT will not manage servers.', 'What fits?', ['QuickSight: serverless BI with pay-per-session pricing — dashboards over Athena/RDS/Redshift with zero servers for IT to run.', 'Self-hosted BI on EC2.', 'Redshift cluster for dashboards.', 'Email CSV exports.'], 0, "The correct answer is the serverless BI service: QuickSight's per-session pricing fits 20 viewers and its managed nature fits the no-servers constraint. Self-hosted EC2 contradicts the requirement.", 'Which service provides dashboards without server management?', ['Choose QuickSight for serverless BI', 'Use pay-per-session economics', 'Consume from the analytics pipeline'], 10, [['Constraints', '20 viewers, daily dashboards, zero server management']]), ('clf-an-pipeline', 'Name That Stage', "A question describes: 'IoT temperature data must be collected continuously, stored durably, transformed nightly, and shown on dashboards.'", 'What is the exam technique for mapping services?', ['Memorize 50 service descriptions.', 'Pipeline thinking: assign each verb a stage — collect (Kinesis), store (S3), transform (Glue/EMR), visualize (QuickSight) — then pick the service per stage instead of guessing one service for everything.', 'Pick the most powerful service mentioned.', 'Choose whatever is serverless.'], 1, "The correct answer is the method, not a service: decomposing the scenario into pipeline stages turns 'which service' into five easy lookups. CLF-C02 analytics questions are stage questions wearing service costumes.", 'How do you decompose a multi-requirement analytics scenario?', ['Decompose scenarios into pipeline stages', 'Map verbs to services', 'Avoid one-service-fits-all'], 10, [['Scenario verbs', 'collected continuously / stored durably / transformed nightly / dashboards']]), ('clf-an-redshift-spec', 'Spectrum vs Redshift', 'An analyst needs to join 50 GB of hot sales data with 10 TB of cold historical data in S3, queried weekly.', 'What is the most cost-effective approach?', ['Athena for everything.', 'EMR weekly job.', 'Redshift Spectrum: query the cold S3 data in place from Redshift without loading it — hot data stays in the cluster, cold data stays cheap in S3, joined in one query.', 'Load all 10 TB into Redshift.'], 2, 'The correct answer keeps cold data cold: Spectrum extends Redshift queries to S3, so the 10 TB avoids expensive cluster storage while still joining with hot data. Loading it all wastes money; Athena alone cannot join efficiently at this shape.', 'How do you query S3 data from Redshift without loading it?', ['Use Redshift Spectrum for S3 joins', 'Tier hot vs cold data', 'Optimize warehouse storage cost'], 15, [['Data', '50 GB hot + 10 TB cold in S3; weekly join queries']]), ('clf-an-stream-fraud', 'Real-Time Fraud', 'A payment company must score transactions for fraud within 2 seconds, with custom ML per transaction, at 10k TPS.', 'Which streaming design fits?', ['Firehose to S3, then Athena.', 'Nightly EMR batch.', 'SQS standard queue.', 'Kinesis Data Streams with consumer applications: ordered per-key processing, custom ML scoring logic per event, and shard-scaled throughput for 10k TPS — Firehose cannot run custom per-record logic.'], 3, 'The correct answer needs custom per-event processing at scale: Data Streams gives consumers full control with ordering guarantees per shard key. Firehose is delivery-only; batch options miss the 2-second SLA.', 'Which service supports custom per-record stream processing?', ['Choose Data Streams for custom logic', 'Design for sub-second streaming SLAs', 'Scale with shards'], 10, [['SLA', 'Fraud score in <2s per transaction; 10k TPS; custom ML per event']])], icon='📊'),)
    did = 'migration'
    (std(did, 'Migration to AWS', 'The 6 Rs, CAF, and the migration toolset: how the exam expects you to think about moving to the cloud.', [('The 6 Rs of Migration', ["Rehost ('lift and shift'): move as-is to EC2 — fastest, least change, but brings old inefficiencies to the cloud", "Replatform ('lift and reshape'): small optimizations during the move (RDS instead of self-managed DB) — the pragmatic middle", 'Repurchase: drop the old app for SaaS — move to a different product entirely (e.g., on-prem CRM → cloud CRM)', 'Refactor/Re-architect: rebuild cloud-native (microservices, serverless) — highest effort, highest long-term payoff; Retain: keep on-premises (for now); Retire: turn it off'], 'R-picker:\n  500 VMs, deadline 6 months -> Rehost, then optimize\n  Self-managed DB, team tired of patching -> Replatform to RDS\n  Old ticket system, SaaS exists -> Repurchase\n  Monolith blocking releases -> Refactor (phase 2)\n\nDeadlines pick the R.', "The exam's R questions always hinge on constraints: tight deadline + minimal change = Rehost; willing to change for managed benefits = Replatform; 'move to SaaS' in the stem = Repurchase. Read the constraint, not the technology.", ['Refactoring everything under a 6-month deadline — the classic failure', 'Rehosting and declaring victory — no optimization ever follows', 'Repurchase confused with Replatform'], 'A factory has 200 VMs and 9 months to exit the data center: which R, and what is phase 2?'), ('AWS CAF: The Migration Framework', ['The Cloud Adoption Framework organizes migration into 6 perspectives: Business, People, Governance, Platform, Security, Operations — migration is not just servers', 'Business perspective: the business case — TCO comparison, value metrics, and stakeholder alignment before any technical work', 'People perspective: roles, skills, and training — the team must be able to operate what you migrate to', 'Security and Governance perspectives: compliance, risk, and controls travel WITH the workloads — they are not phase 2'], 'CAF check:\n  Business: TCO model approved? [ ]\n  People: cloud skills plan? [ ]\n  Governance: cost controls? [ ]\n  Platform: landing zone ready? [ ]\n  Security: controls mapped? [ ]\n  Operations: runbooks updated? [ ]\n\nSix boxes, all checked.', 'CAF questions test breadth: the wrong answers focus only on technology. If a scenario mentions skills gaps, compliance, or cost governance, the answer lives in the non-technical perspectives.', ['Treating migration as a pure infrastructure project', 'Skipping the business case — migrating without knowing why', 'Security as an afterthought instead of a perspective'], "A migration stalled on 'nobody knows who approves cloud spend': which CAF perspective failed?"), ('Migration Tools: DMS, MGN, and DataSync', ['Application Migration Service (MGN): lift-and-shift for servers — replicates EC2/VMs continuously and cuts over with minimal downtime; the Rehost workhorse', 'DMS: database migration with ongoing replication (plus SCT for schema conversion) — the data-layer counterpart to MGN', 'DataSync: fast, managed data transfer — NFS/SMB/HDFS to S3/EFS/FSx, with scheduling, validation, and bandwidth control', 'Exam mapping: servers with minimal downtime → MGN; databases → DMS; file shares at speed → DataSync'], 'Tool picker:\n  300 VMs, minimal downtime -> MGN\n  Oracle DB -> Aurora -> DMS + SCT\n  50 TB file share -> S3 -> DataSync\n  5 PB datacenter exit -> Snowball/Snowmobile\n\nWorkload type picks the tool.', 'Keep MGN (servers) and DMS (databases) surgically separate in your head: the exam deliberately pairs a server-migration scenario with DMS as a distractor. Servers → MGN; databases → DMS — no exceptions.', ['DMS for server lift-and-shift — wrong tool', 'MGN for database migration — wrong tool', 'Manual rsync for 50 TB — DataSync exists for this'], '200 VMs + Oracle DB, minimal downtime: which two services, and what does each move?'), ('Snow Family: Moving Data at Scale', ['Snowcone: small, portable edge device (8 TB) — rugged collection and edge compute where networks are poor', "Snowball: 80 TB per device, clustered for petabyte moves — the workhorse for 'too big for the network' transfers", 'Snowmobile: a literal truck — exabyte-scale datacenter evacuation when even Snowballs would take too long', 'Rule of thumb: under ~100 TB with good bandwidth → network (Direct Connect/DataSync); beyond that → Snow; beyond petabytes → Snowmobile'], 'Transfer math:\n  500 TB over 1 Gbps ≈ 46 days -> Snowball fleet\n  500 TB over 10 Gbps ≈ 4.6 days -> DataSync/Direct Connect\n  8 EB datacenter -> Snowmobile\n\nBandwidth x time decides.', "The exam's Snow questions are math-free but logic-heavy: 'limited connectivity' or 'petabytes' in the stem = Snow family; the device size in the answers distinguishes Cone/Ball/Mobile. Read for scale words.", ['Snowball for 500 GB — network is faster and cheaper', 'Network transfer for 5 PB over 1 Gbps — do the math', "Forgetting Snowcone's edge-compute role"], 'A ship generates 20 TB/voyage with no connectivity at sea: which Snow device, and why?'), ('Migration Strategies and Landing Zones', ['Land well first: a landing zone (via Control Tower) gives every migration guardrails — accounts, SSO, logging, and SCPs — before the first workload moves', 'Wave planning: migrate in waves by dependency (low-risk, low-dependency first) — each wave proves the pattern for the next', 'The 3-phase rhythm: Assess (discover, TCO, R-select) → Mobilize (landing zone, skills, pilot) → Migrate & Modernize (waves, then optimize)', 'Post-migration is not done: decommission the old, validate the bills against the TCO model, and schedule the Replatform/Refactor phase Rehost deferred'], 'Wave plan:\n  Wave 0: landing zone + pilot (1 app)\n  Wave 1: independent dev/test (20 apps)\n  Wave 2: production, low dependency (50 apps)\n  Wave 3: complex/coupled (remaining)\n\nProve, then scale.', "Migrations fail on dependencies, not technology: discover application dependencies BEFORE wave planning (Migration Evaluator/Application Discovery Service), or wave 2 will drag wave 1's databases along with it.", ['Migrating without dependency discovery — coupling surprises', 'No landing zone — every team invents its own guardrails', 'Declaring victory at cutover — optimization never happens'], 'Sketch waves 0-2 for a 100-app estate with a tangled ERP core: what moves when?')], [('clf-mig-r', 'Pick the R', "A retailer must vacate its data center in 5 months: 400 VMs, no code changes allowed by the business, optimization 'later.'", 'Which strategy fits?', ['Rehost: lift-and-shift the VMs as-is (via MGN) to meet the hard deadline with zero application changes — optimization becomes the explicit phase 2.', 'Refactor to microservices.', 'Repurchase everything as SaaS.', 'Retire the data center immediately.'], 0, "The correct answer honors the constraints: 5 months + no code changes rules out Refactor and Repurchase. Rehost meets the deadline; the 'later' optimization must be a scheduled phase, not a wish.", 'Which R means move as-is with no changes?', ['Apply Rehost to deadline migrations', 'Read constraints before technology', 'Schedule phase-2 optimization'], 10, [['Constraints', '5-month exit, 400 VMs, zero code changes permitted']]), ('clf-mig-replatform', 'The Tired DBA', 'A company migrates its self-managed PostgreSQL to AWS. The DBA team spends 30% of its time patching and managing replicas, and wants out of that work.', 'Which approach fits?', ['Repurchase a SaaS database.', 'Replatform to RDS/Aurora PostgreSQL: move with a small change (managed database instead of self-managed) that eliminates the patching/replica toil while keeping Postgres compatibility.', 'Rehost PostgreSQL on EC2.', 'Refactor to DynamoDB.'], 1, "The correct answer is the 'lift and reshape' middle: changing the platform (self-managed → managed) during migration captures the operational win without a rewrite. Rehost preserves the toil; DynamoDB forces a data-model rewrite.", 'Which R changes the platform slightly for managed benefits?', ['Apply Replatform for managed services', 'Eliminate undifferentiated labor', 'Keep compatibility while improving ops'], 10, [['Pain', 'DBAs spend 30% time on patching/replicas; Postgres must stay']]), ('clf-mig-caf', 'The Stalled Migration', 'Six months into a migration, teams spin up resources with no tagging, nobody knows the cloud bill owners, and security has not reviewed a single workload.', 'Which CAF perspectives failed?', ['Business — migrations never need business cases.', 'Operations — runbooks are optional.', 'Governance (cost controls, tagging, account structure) and Security (controls traveling with workloads) — the migration moved servers while the guardrails stayed behind.', 'Platform — the servers are wrong.'], 2, 'The correct answer names the non-technical gap: untagged spend with no owners is Governance; unreviewed workloads are Security. CAF exists because migrations fail on exactly these perspectives while the technology works fine.', 'Which perspectives cover cost control and compliance?', ['Apply CAF beyond technology', 'Diagnose governance failures', 'Build guardrails before workloads'], 15, [['Symptoms', 'No tagging, unknown bill owners, zero security reviews at month 6']]), ('clf-mig-mgn', 'Servers vs Databases', 'A factory migrates 150 VMs and 3 SQL Server databases to AWS with minimal downtime. The architect proposes DMS for everything.', 'What is wrong with the plan?', ['Nothing — DMS handles servers too.', 'MGN is only for databases.', 'Both should use Snowball.', 'Wrong tool for servers: DMS migrates DATABASES; the 150 VMs need Application Migration Service (MGN). Use MGN for servers, DMS (+SCT) for the SQL Server databases.'], 3, 'The correct answer keeps the tool boundary crisp: MGN = server lift-and-shift with continuous replication; DMS = database migration. The exam plants exactly this confusion as a distractor.', 'Which service lift-and-shifts servers, and which migrates databases?', ['Separate MGN from DMS', 'Map tools to workload types', 'Spot exam distractors'], 10, [['Plan', '150 VMs + 3 SQL Server DBs; architect proposed DMS for all']]), ('clf-mig-snow', 'The Bandwidth Wall', 'A media company must move 3 PB of archives to S3. Their uplink is 500 Mbps and the CFO will not pay for a bigger circuit.', 'What is the practical path?', ['Snowball fleet (or Snowmobile assessment): 3 PB over 500 Mbps takes ~1.5 years — physical transfer devices are the only sane option at this scale and bandwidth.', 'DataSync over the 500 Mbps link.', 'Direct Connect 10 Gbps.', 'S3 multipart upload from the office.'], 0, "The correct answer does the transfer math: petabytes over megabits means years — Snow devices convert network-years into shipping-days. The CFO's constraint actually forces the Snow decision.", 'At what scale does physical transfer beat the network?', ['Apply Snow family at petabyte scale', 'Do transfer-time math', 'Respect bandwidth constraints'], 10, [['Math', '3 PB / 500 Mbps ≈ 550 days; CFO rejects circuit upgrade']]), ('clf-mig-datasync', 'The File Share', 'A design studio needs its 30 TB NFS file share in S3, synced nightly, with validation that files arrived intact.', 'Which service fits?', ['Manual rsync cron jobs.', 'DataSync: managed, fast NFS/SMB-to-S3 transfer with scheduling, bandwidth throttling, and built-in data validation — purpose-built for this.', 'Snowcone.', 'DMS.'], 1, 'The correct answer is the file-transfer service: DataSync handles protocols, scheduling, and integrity checking natively. Snowcone is for edge/offline; DMS is databases; rsync is toil.', 'Which service moves file shares to S3 with validation?', ['Choose DataSync for file transfers', 'Use managed validation', 'Avoid manual transfer toil'], 10, [['Needs', '30 TB NFS -> S3, nightly sync, integrity validation']]), ('clf-mig-wave', 'Wave Zero', "An enterprise plans to migrate 300 applications. The proposal starts with 'migrate the ERP in month one to show progress.'", 'What is wrong with the sequencing?', ['Migrate alphabetically instead.', 'Skip the landing zone to save time.', 'Wave discipline: start with the landing zone + a low-risk pilot (Wave 0), then independent apps — the coupled ERP core migrates LAST, after the pattern is proven. Leading with the hardest workload maximizes blast radius.', 'Nothing — big wins first.'], 2, "The correct answer sequences by risk and dependency: Wave 0 proves the landing zone and runbooks on something forgiving; the ERP's coupling makes it the worst possible first move. Progress theater is not progress.", 'How should migration waves be sequenced?', ['Sequence waves by risk', 'Prove patterns with pilots', 'Defer coupled cores'], 15, [['Proposal', '300 apps; ERP (most coupled) proposed for month one']]), ('clf-mig-eval', 'The Unknown Estate', 'A company acquired a data center with 600 undocumented servers. Nobody knows what depends on what, or what anything costs to run.', 'What comes before wave planning?', ['Start migrating immediately.', 'Interview every former admin.', 'Guess the dependencies from hostnames.', 'Discovery and assessment: Application Discovery Service / Migration Evaluator to map dependencies and build the TCO business case — you cannot sequence what you cannot see.'], 3, 'The correct answer is assess-before-migrate: dependency mapping prevents wave collisions and the TCO model justifies the program. Migrating blind turns unknown coupling into outages.', 'What must precede migration wave planning?', ['Discover before migrating', 'Map dependencies', 'Build the TCO business case'], 10, [['Estate', '600 undocumented servers; zero dependency knowledge; no cost baseline']])], icon='🚚'),)
    did = 'well-architected'
    (std(did, 'Well-Architected Framework', "The six pillars and their design principles: the exam's favorite 'best practice' questions.", [('The Six Pillars', ['Operational Excellence: run and monitor systems to deliver business value — IaC, small reversible changes, learn from failure', 'Security: protect data and systems — least privilege, encryption everywhere, automate security, traceability', 'Reliability: recover from failure — auto-recovery, scale horizontally, stop guessing capacity, test recovery', 'Performance Efficiency: use resources efficiently — right-sizing, experimentation, mechanical sympathy; Cost Optimization: avoid waste — pay-as-you-go, measure efficiency; Sustainability: minimize environmental impact'], 'Pillar one-liners:\n  Ops: run it well, change it safely\n  Security: least privilege + encryption + automation\n  Reliability: survive failure automatically\n  Performance: right resource, right job\n  Cost: pay for value, kill waste\n  Sustainability: efficient = green\n\nSix lenses, one architecture.', "Exam questions describe a PRACTICE and ask for the pillar: 'automated backups and multi-AZ' → Reliability; 'MFA and encryption' → Security; 'turning off idle resources' → Cost Optimization. Learn the practice-to-pillar mapping.", ['Memorizing pillar names without their practices', 'One pillar to the exclusion of others — tradeoffs are the point', 'Treating Sustainability as optional — it is a scored pillar'], 'Take three practices (auto-scaling, KMS encryption, Savings Plans) and name each pillar.'), ('Security Pillar Design Principles', ['Strong identity foundation: centralize identity, enforce MFA, use temporary credentials (roles) over long-lived keys', 'Least privilege and traceability: grant only needed permissions; log everything (CloudTrail) so actions are auditable', 'Security at every layer: defense in depth — edge (WAF/Shield), network (security groups), compute (patching), data (encryption)', 'Automate security: guardrails as code (Config rules, SCPs), secrets in Secrets Manager — humans should not hand-handle credentials'], 'Security checklist:\n  [ ] MFA on root + IAM users\n  [ ] Roles, not access keys, for apps\n  [ ] Encryption at rest (KMS) + in transit (TLS)\n  [ ] CloudTrail enabled, logs immutable\n  [ ] Security groups deny-by-default\n\nAutomate every line.', "The exam's security questions reward the strictest correct option: given a choice between 'open security group to the world' convenience and least-privilege, the Framework always picks least privilege — even when it is more work.", ['Long-lived access keys embedded in applications', "Security groups open to 0.0.0.0/0 'temporarily'", 'Manual security reviews instead of Config rules'], 'Audit a hypothetical app: list 5 security-pillar violations and their fixes.'), ('Reliability Pillar Design Principles', ['Automatic recovery: design for failure — health checks, auto-restart, and failover that needs no human at 3 AM', 'Scale horizontally: add more small units instead of bigger ones — AZ distribution plus load balancing over vertical scaling', 'Stop guessing capacity: auto-scaling on demand signals beats provisioned-for-peak waste and provisioned-for-average outages', 'Test recovery: game days and chaos drills — untested failover is a hope, and hope is not a pillar'], 'Reliability patterns:\n  EC2 -> Auto Scaling group across 3 AZs\n  RDS -> Multi-AZ with automated backups\n  Static -> S3 + CloudFront (11 9s durability)\n  Queue -> SQS decouples, absorbs spikes\n\nEvery tier survives a failure.', "Reliability questions hinge on automation: the Framework prefers the answer where recovery happens WITHOUT human intervention. 'An operator fails over manually' is always the wrong answer next to 'automated failover.'", ["Single AZ deployments called 'reliable'", 'Manual failover runbooks as the HA strategy', 'Vertical scaling as the growth plan'], 'Design the reliability story for a 3-tier app: what fails, what recovers automatically?'), ('Cost Optimization Pillar', ['Pay only for what you use: right-size instances, delete unattached EBS volumes and idle load balancers — waste is the default without hygiene', 'Measure efficiency: Cost Explorer, Compute Optimizer rightsizing recommendations, and per-team cost allocation tags', 'Commit where predictable: Savings Plans/RIs for steady state; Spot for interruptible; On-Demand nowhere long-term', 'Design for cost: serverless and auto-scaling align cost with demand — the cheapest resource is the one that does not exist when idle'], 'Cost hygiene loop (monthly):\n  1. Cost Explorer: top 5 services by spend\n  2. Compute Optimizer: rightsizing actions\n  3. Trusted Advisor: idle resources\n  4. Tag compliance: 100% of spend attributed\n  5. Commit review: coverage vs usage\n\nWaste compounds; so does hygiene.', "Cost questions test the 'cheapest correct' instinct: the Framework never picks the expensive easy answer when a cheaper managed answer exists. But 'cheapest' never means 'less reliable than the requirement' — requirements bound the optimization.", ['On-Demand forever on flat workloads', 'Untagged spend nobody owns', "Idle resources 'in case we need them'"], 'Run the monthly cost hygiene loop on a hypothetical $20k/mo bill: where is the waste?'), ('Performance Efficiency and Sustainability', ['Performance: select the right resource types (compute/memory/GPU families), use serverless to remove idle, and experiment — benchmark, do not guess', 'Mechanical sympathy: understand the underlying tech — EBS volume types, S3 request rates, database indexing — and design WITH it, not against it', 'Sustainability: utilization is the lever — higher utilization means fewer resources for the same work; managed and serverless services maximize it', 'The shared model: efficient architectures are BOTH cheaper and greener — Cost Optimization and Sustainability usually agree'], 'Efficiency wins:\n  Graviton instances: 40% better price-performance\n  Auto-scaling: no idle over-provisioning\n  S3 Intelligent-Tiering: automatic cost fit\n  Right region: closer = faster + less transfer\n\nEfficiency compounds across pillars.', "Sustainability questions are the exam's newest favorite: the answers always involve utilization, managed services, and efficient instance types (Graviton). 'Run idle servers just in case' fails both cost AND sustainability.", ['Guessing instance types instead of benchmarking', "Idle over-provisioning 'for headroom'", 'Ignoring Graviton price-performance'], 'Name three changes that improve cost AND sustainability simultaneously.')], [('clf-wa-pillar', 'Name the Pillar', 'A team enables MFA everywhere, encrypts all EBS volumes with KMS, and turns on CloudTrail with immutable log storage.', 'Which pillar do these practices belong to?', ["Security: identity controls (MFA), encryption (KMS), and traceability (CloudTrail) are the Security pillar's core practices.", 'Reliability.', 'Operational Excellence.', 'Cost Optimization.'], 0, "The correct answer maps practices to pillars: MFA + encryption + audit logging is the Security pillar's unmistakable signature. The exam's pillar questions are practice-recognition, not definition recall.", "Which practices are the Security pillar's signature?", ['Map practices to pillars', 'Recognize security controls', 'Apply the Framework lens'], 10, [['Changes', 'MFA enforced, KMS encryption, immutable CloudTrail logs']]), ('clf-wa-rel', 'The 3 AM Test', 'A database fails over manually: an operator gets paged, runs the runbook, and restores service in 40 minutes. Twice this quarter.', 'What does the Reliability pillar prescribe?', ['Bigger database instance.', 'Automated recovery: Multi-AZ with automatic failover removes the operator from the critical path — the pillar demands recovery WITHOUT human intervention, tested regularly.', 'A faster runbook.', 'More operators on call.'], 1, "The correct answer is the pillar's core principle: design systems that recover automatically. Manual runbooks, however fast, violate 'automatic recovery from failure' — and 40 minutes of downtime twice a quarter is the cost.", "What does 'automatic recovery from failure' require?", ['Automate failover', 'Remove humans from recovery paths', 'Test recovery procedures'], 10, [['Incidents', '2 manual failovers this quarter, 40 min MTTR each']]), ('clf-wa-cost', 'The Idle Fleet', 'Cost Explorer shows 30 EC2 instances averaging 4% CPU for 6 months, plus 2 TB of unattached EBS volumes. Nobody claims them.', 'What is the Cost Optimization response?', ['It is only 4% — leave them.', 'Move them to Spot.', 'Hygiene first: terminate or right-size the idle instances, delete unattached volumes (snapshot first), tag everything with owners, and set up Trusted Advisor + Budgets alerts so waste cannot accumulate silently again.', 'Buy Reserved Instances for them.'], 2, "The correct answer treats waste as the default state: the pillar's first move is eliminating what should not exist, then committing only on the right-sized remainder. Reserving waste just discounts it.", 'What is the first step of cost optimization?', ['Eliminate idle resources', 'Right-size before committing', 'Automate waste detection'], 10, [['Waste', '30 instances at 4% CPU, 2 TB unattached EBS, 6 months']]), ('clf-wa-tradeoff', 'The Tradeoff Question', 'A proposal cuts cost 30% by running production in a single AZ. The architect objects on Reliability grounds.', 'How does the Framework resolve this?', ['Cost wins; 30% is 30%.', 'Reliability always beats cost.', 'Split the difference: 1.5 AZs.', 'Requirements bound optimization: the Framework demands BOTH pillars be satisfied — cost cannot be cut below the reliability the business requires. Single-AZ for production fails Reliability regardless of savings; find cost wins that preserve the SLA.'], 3, "The correct answer applies the Framework as a system: pillars constrain each other, and business requirements set the floor. 'Cheapest' is never correct when it violates a stated reliability requirement.", 'How do pillars interact under competing proposals?', ['Balance pillars against requirements', 'Reject false cost savings', 'Apply requirements as constraints'], 15, [['Proposal', '-30% cost via single-AZ production; SLA requires 99.9%']]), ('clf-wa-sustain', 'The Green Question', 'A company wants to reduce its cloud carbon footprint. Its workloads run on older instance types at 15% average utilization.', 'What helps most?', ['Raise utilization with modern efficient instances: migrate to Graviton (better price-performance per watt), enable auto-scaling to kill idle capacity, and prefer serverless/managed services — efficiency is the sustainability lever.', 'Buy carbon offsets only.', 'Move to the cheapest region.', 'Turn off CloudTrail logging.'], 0, "The correct answer is the Sustainability pillar's core mechanic: higher utilization + efficient silicon = less energy per unit of work. Offsets do not change the footprint; the other options are irrelevant or harmful.", "What is the Sustainability pillar's primary lever?", ['Improve utilization for sustainability', 'Choose efficient instance types', 'Prefer serverless and managed'], 10, [['Footprint', 'Legacy instances, 15% utilization, carbon-reduction goal']]), ('clf-wa-ops', 'The Change Failure', 'Production changes are big-bang Friday deploys. Rollbacks take hours, and every deploy is feared.', "Which pillar's practices fix this?", ['Buy bigger instances.', "Operational Excellence: small reversible changes, IaC, automated testing, and deployment safeguards (canary/blue-green) — the pillar's 'evolve safely' principle replaces fear with routine.", 'Security.', 'Performance Efficiency.'], 1, 'The correct answer maps the practice set: IaC, small reversible changes, and safe deployment patterns are Operational Excellence signatures. The fear is the symptom; the change process is the disease.', 'Which practices define Operational Excellence?', ['Apply IaC and safe deployments', 'Make changes small and reversible', 'Automate operations'], 10, [['Process', 'Big-bang Friday deploys, hours-long rollbacks, deploy fear']]), ('clf-wa-review', 'The Review Cadence', 'A team did one Well-Architected review at launch two years ago. The architecture has tripled in size since.', 'What does the Framework recommend?', ['Reviews are only for audits.', 'Rewrite everything instead.', 'Review as a habit: re-run the Well-Architected review on significant changes and on a cadence — architectures drift, new services appear, and the review catches drift before incidents do.', 'One review is enough forever.'], 2, 'The correct answer treats the review as continuous improvement, not a checkbox: the Framework is a living practice, and a two-year-old review describes an architecture that no longer exists.', 'How often should architectures be reviewed?', ['Review continuously', 'Catch drift with cadence', 'Treat the Framework as living practice'], 10, [['History', 'One review 2 years ago; architecture 3x larger since']])], icon='🏛️'),)
    labs += [LB('lab-clf-athena', 'Athena Query Cost Lab', 'Query ALB logs in S3 with Athena, then cut the scan cost with Parquet and partitioning.', ['Create the table over raw CSV logs; run a 7-day query and record bytes scanned', 'Convert the data to Parquet partitioned by date (Glue job or CTAS)', 'Re-run the same query; record the new bytes scanned and cost delta', 'Document the rule: when does Athena beat Redshift, and vice versa'], [('ls athena-cost-compare.md', 'Parquet', 'cost comparison missing — run both queries first')], 'Athena cost mechanics learned hands-on. Format and partitioning are now cost controls.'), LB('lab-clf-migration', 'Migration Wave Plan', 'Produce a wave plan for a 60-app estate: Rs, tools, waves, and landing zone.', ['Inventory 60 hypothetical apps: dependencies, data stores, compliance tags', 'Assign an R to each app with a one-line justification', 'Sequence 4 waves: landing zone + pilot, independent apps, production, coupled core', 'Map tools per wave: MGN for servers, DMS for databases, DataSync for files'], [('ls wave-plan.md', 'Wave 0', 'wave plan missing — inventory the estate first')], 'Migration planned in waves with tools mapped. The estate now moves in order, not chaos.'), LB('lab-clf-wa-review', 'Well-Architected Self-Review', 'Run a Well-Architected review on a sample 3-tier architecture and remediate the top 3 risks.', ['Document the architecture: VPC, ALB, EC2 Auto Scaling, RDS Multi-AZ, S3 + CloudFront', 'Score each pillar: list 2 findings per pillar with severity', 'Remediate the top 3 risks (e.g., no MFA on root, single-AZ RDS, unencrypted EBS)', 'Write the improvement plan: risk, fix, effort, pillar'], [('ls wa-review.md', 'High', 'review missing — score all six pillars first')], 'Well-Architected review complete with remediations. The architecture now has a risk ledger.'), LB('lab-clf-dr', 'Backup and Restore Drill', 'Prove recovery works: back up an RDS database and a set of EBS volumes, then restore and verify.', ['Enable automated RDS backups; take a manual snapshot and record the RPO', 'Simulate failure: restore the snapshot to a new instance and measure RTO', 'Test EBS snapshots: create, restore as a new volume, attach, verify data', 'Document the runbook: RPO/RTO achieved, steps, and gaps found'], [('ls dr-drill-report.md', 'RTO', 'drill report missing — run the restore first')], 'Recovery proven by drill, not assumed. RPO/RTO are now measured facts.')]
    return (new_domains, labs)
